#include <iostream>
#include <valarray>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 1 || n > 1000) return 1;
    std::valarray<long long> values(0LL, static_cast<std::size_t>(n));
    for (int i = 0; i < n; i++) {
        long long value = 0;
        if (!(std::cin >> value)) return 1;
        if (value < -10000 || value > 10000) return 1;
        values[static_cast<std::size_t>(i)] = value;
    }
    std::valarray<long long> doubled = values * 2LL;
    std::cout << doubled.sum() << std::endl;
    return 0;
}
